<script setup lang="ts">
import {computed,ref} from 'vue'
import {useI18n} from 'vue-i18n'
import {newSettlementEvidence} from '../supplemental'
import {copy,validMoney} from '../payrollUi'
import type {SettlementEvidence,SettlementEvidencePage,ReconciliationPage} from '../supplemental'
const props=defineProps<{page:SettlementEvidencePage;locked:boolean;reconciliations?:ReconciliationPage[];reconciliationsLoading?:boolean}>(),emit=defineEmits<{save:[body:SettlementEvidence];loadReconciliations:[]}>(),{locale}=useI18n(),x=(z:string,e:string)=>locale.value.startsWith('en')?e:z
const draft=ref(copy(props.page.evidence||newSettlementEvidence(props.page.version))),error=ref(''),cdacMode=ref(draft.value.cdacProfile?.status||''),recoveryCause=ref(draft.value.recovery?.cause||'')
if(!draft.value.interest)draft.value.interest={state:'unknown',assessedAmount:null,officialReference:null}
if(!draft.value.recovery)draft.value.recovery={cause:'unclassified',legalBasis:null,dueYear:null,deadline:null,maximum:null,evidenceReference:null,reconciliationId:null}
const eligibleReconciliations=computed(()=>(props.reconciliations||[]).filter(p=>p.reconciliation.companyId===props.page.companyId&&p.reconciliation.employeeId===props.page.employeeId&&p.reconciliation.year===Number(props.page.month.slice(0,4))))
const unlistedReference=computed(()=>draft.value.recovery?.reconciliationId&&!eligibleReconciliations.value.some(p=>p.reconciliation.id===draft.value.recovery?.reconciliationId))
const labels=()=>({employeeCpf:x('原实缴员工CPF','Opening remitted employee CPF'),employerCpf:x('原实缴雇主CPF','Opening remitted employer CPF'),sdl:x('原实缴SDL（员工依据）','Opening remitted SDL (employee evidence)'),cdac:x('原实缴CDAC','Opening remitted CDAC')})
function profile(){draft.value.cdacProfile=cdacMode.value?{status:cdacMode.value as NonNullable<SettlementEvidence['cdacProfile']>['status'],reference:draft.value.cdacProfile?.reference||''}:null}
function save(){if(props.locked||!props.page.writable)return;const d=copy(draft.value);const selected=d.recovery?.reconciliationId;if(recoveryCause.value==='aw_statutory_reassessment'&&selected&&selected!==props.page.evidence?.recovery?.reconciliationId&&!eligibleReconciliations.value.some(p=>p.reconciliation.id===selected)){error.value=x('请选择已读取且匹配本公司、员工和原年度的真实AW复核。','Select a loaded AW reconciliation matching this company, employee and original year.');return}for(const key of ['employeeCpfDeducted','cdacDeducted','recognisedSdl','recognisedCdac','manualCdac'] as const)d[key]=d[key]||null;for(const key of ['employeeCpf','employerCpf','sdl','cdac'] as const)d.remitted[key]=d.remitted[key]||null;if(d.interest){d.interest.assessedAmount=d.interest.state==='assessed'?(d.interest.assessedAmount||null):null;d.interest.officialReference=d.interest.officialReference?.trim()||null}d.recovery=recoveryCause.value&&d.recovery?{...d.recovery,cause:recoveryCause.value,reconciliationId:d.recovery.reconciliationId||null,maximum:d.recovery.maximum||null,dueYear:d.recovery.dueYear?Number(d.recovery.dueYear):null}:null;const amounts=[d.employeeCpfDeducted,d.cdacDeducted,d.recognisedSdl,d.recognisedCdac,d.manualCdac,...Object.values(d.remitted),d.recovery?.maximum,d.interest?.assessedAmount];if(!d.evidenceReference.trim()||amounts.some(v=>v!==null&&v!==undefined&&!validMoney(v))||(d.interest?.state==='assessed'&&(!d.interest.assessedAmount||!d.interest.officialReference))||(d.interest?.state==='not_applicable'&&!d.interest.officialReference)){error.value=x('请核对有凭证的事实；留空表示未知，官方核定／不适用利息必须有依据。','Review evidenced facts. Blank means unknown; assessed / inapplicable interest requires evidence.');return}d.commandId=crypto.randomUUID();d.expectedVersion=props.page.version;error.value='';emit('save',d)}
</script>
<template><form class="wf-section" @submit.prevent="save"><h3>{{x('历史实扣／实缴与法定依据','Opening deduction / remittance and statutory evidence')}}</h3><p class="wf-hint">{{x('留空为未知；只有凭证证明为零才录0。新缴纳另用缴纳登记，不覆盖这些原事实，也不改原工资。','Blank means unknown; enter zero only with evidence. Record new remittances separately without replacing opening facts or payroll.')}}</p><fieldset :disabled="locked||!page.writable"><label>{{x('原事实凭证','Opening fact evidence')}}<textarea v-model="draft.evidenceReference" required maxlength="1000" :aria-label="x('原事实凭证','Opening fact evidence')"/></label><label>{{x('发现日期','Discovery date')}}<input v-model="draft.discoveryDate" type="date"></label><div class="wf-grid"><label>{{x('原实际已扣员工CPF','Opening employee CPF deducted')}}<input v-model="draft.employeeCpfDeducted" inputmode="decimal" :aria-label="x('原实际已扣员工CPF','Opening employee CPF deducted')"></label><label>{{x('原实际已扣CDAC','Opening CDAC deducted')}}<input v-model="draft.cdacDeducted" inputmode="decimal"></label><label v-for="(label,key) in labels()" :key="key">{{label}}<input v-model="draft.remitted[key]" inputmode="decimal" :aria-label="label"></label><label>{{x('外部原SDL责任','Opening recognised SDL')}}<input v-model="draft.recognisedSdl" inputmode="decimal"></label><label>{{x('外部原CDAC责任','Opening recognised CDAC')}}<input v-model="draft.recognisedCdac" inputmode="decimal"></label></div><details><summary>{{x('外部原CDAC批准口径','Opening approved CDAC treatment')}}</summary><label>{{x('原CDAC处理方式','Opening CDAC mode')}}<select v-model="cdacMode" @change="profile"><option value="">{{x('未知','Unknown')}}</option><option value="applicable">{{x('按规则适用','Applicable')}}</option><option value="not_applicable">{{x('不适用','Not applicable')}}</option><option value="exempt">{{x('有依据豁免','Exempt with evidence')}}</option><option value="manual">{{x('手动核对','Manual')}}</option></select></label><label v-if="draft.cdacProfile">{{x('原CDAC核对依据','Opening CDAC evidence')}}<textarea v-model="draft.cdacProfile.reference" maxlength="500"/></label><label>{{x('原手工CDAC金额','Opening manual CDAC amount')}}<input v-model="draft.manualCdac" inputmode="decimal"></label><button v-if="!draft.cdacReview" type="button" @click="draft.cdacReview={amount:'',note:''}">{{x('记录外部原手动覆盖','Record opening override')}}</button><template v-if="draft.cdacReview"><label>{{x('原覆盖金额','Opening override amount')}}<input v-model="draft.cdacReview.amount" inputmode="decimal"></label><label>{{x('原覆盖依据','Opening override evidence')}}<textarea v-model="draft.cdacReview.note"/></label><button type="button" @click="draft.cdacReview=null">{{x('清除未保存覆盖','Clear draft override')}}</button></template></details><section v-if="draft.recovery"><h4>{{x('追回资格事实（不自动扣工资）','Recovery facts (no automatic wage deduction)')}}</h4><label>{{x('追回成因','Recovery cause')}}<select v-model="recoveryCause"><option value="">{{x('未知','Unknown')}}</option><option value="unclassified">{{x('未分类','Unclassified')}}</option><option value="ordinary_employer_omission">{{x('普通雇主漏扣','Ordinary employer omission')}}</option><option value="ordinary_non_negligent_recovery">{{x('普通非疏忽追回','Ordinary non-negligent recovery')}}</option><option value="aw_statutory_reassessment">{{x('法定AW重新评估','Statutory AW reassessment')}}</option><option value="already_deducted_unremitted">{{x('原已扣未缴','Already deducted, unremitted')}}</option></select></label><section v-if="recoveryCause==='aw_statutory_reassessment'"><button type="button" :disabled="locked||reconciliationsLoading" @click="emit('loadReconciliations')">{{x('读取可关联AW复核','Load eligible AW reconciliations')}}</button><label>{{x('关联原年度AW复核','Original-year AW reconciliation')}}<select v-model="draft.recovery.reconciliationId" :aria-label="x('关联原年度AW复核','Original-year AW reconciliation')"><option :value="null">{{x('缺关联；追回资格尚未确定','No reference; recovery eligibility remains unknown')}}</option><option v-if="unlistedReference" :value="draft.recovery.reconciliationId" disabled>{{x('已保存引用（当前列表未核对）','Saved reference (not verified in current list)')}} {{draft.recovery.reconciliationId}}</option><option v-for="p in eligibleReconciliations" :key="p.reconciliation.id" :value="p.reconciliation.id">{{p.reconciliation.year}} · {{p.reconciliation.settlementMonth}} · {{p.reconciliation.id}}</option></select></label><p class="wf-hint">{{x('仅关联服务器已保存的同公司、员工、原年度复核。合法可追回金额仍由服务器根据实缴、原责任、未扣余额及期限确定，不自动扣工资。','Reference a stored reconciliation for the same company, employee and original year. The server determines eligibility from actual additional remittances, original liability, undeducted balance and deadline; wages are not automatically deducted.')}}</p></section><div class="wf-grid"><label>{{x('法律依据','Legal basis')}}<input v-model="draft.recovery.legalBasis"></label><label>{{x('原应缴年度','Original due year')}}<input v-model="draft.recovery.dueYear" type="number" min="1900" max="9999"></label><label>{{x('法定截止日期','Statutory deadline')}}<input v-model="draft.recovery.deadline" type="date"></label><label>{{x('可追回上限','Recovery maximum')}}<input v-model="draft.recovery.maximum" inputmode="decimal"></label></div><label>{{x('追回适用凭证','Recovery applicability evidence')}}<textarea v-model="draft.recovery.evidenceReference"/></label></section><section v-if="draft.interest"><h4>{{x('官方利息事实','Official interest facts')}}</h4><label>{{x('利息认定','Interest determination')}}<select v-model="draft.interest.state" :aria-label="x('利息认定','Interest determination')"><option value="unknown">{{x('未知，不猜计息','Unknown, no estimated interest')}}</option><option value="assessed">{{x('官方核定','Officially assessed')}}</option><option value="not_applicable">{{x('有依据不适用','Not applicable with evidence')}}</option></select></label><label>{{x('官方核定利息金额','Official interest amount')}}<input v-model="draft.interest.assessedAmount" inputmode="decimal"></label><label>{{x('官方利息／适用依据','Official interest / applicability reference')}}<input v-model="draft.interest.officialReference"></label></section><button type="submit" :disabled="locked||!page.writable">{{x('保存法定事实修订','Save statutory fact revision')}}</button></fieldset><p v-if="error" role="alert">{{error}}</p></form></template>
